from .coco_section_generic import YAMLBasedSectionGeneric


class SectionLogs(YAMLBasedSectionGeneric):
    def __init__(self, section_name='LOGS'):
        super().__init__(section_name)

    def _prepare_section_content(self, *args, **kwargs):
        return {
            'EPC': self._prepare_subsection_epc_content(),
            'CUS': self._prepare_subsection_cus_content(),
        }

    @staticmethod
    def _prepare_subsection_epc_content():
        epc_subsection_content = {
            'log_level': 6,
            'log_file': {
                'max_log_size': 20000000,
                'max_file_num': 5
            }
        }
        return epc_subsection_content

    @staticmethod
    def _prepare_subsection_cus_content():
        # TODO more than one CUS?
        cus_subsection_content = {
            'syslog_ip': '192.168.200.126',
            'syslog_level': 'DBG'
        }
        return cus_subsection_content
